# November 22, 2026: a first statewide scatter across Louisiana, region la, claimed as the state with the fewest places
# (34) by tools/choose.py --thinnest. Earlier batches covered Greater New Orleans (la_kaae) and the Cane River country
# (la_wpfv); this one spreads across the rest of the state: Shreveport, Minden, Monroe, Ferriday, Alexandria and
# Pineville, the Felicianas, Baton Rouge, Thibodaux, New Iberia, St. Martinville and Lake Charles.
# Facts come from the linked sources, opened in this session: Wikipedia read as raw text (wiki_raw.py), and the pages of
# whoever runs each place read through page.py (Shreveport Water Works Museum, the Strand Theatre, Biedenharn Museum,
# Frogmore, Kent House, Afton Villa Gardens, Grace Church, BREC for Magnolia Mound, Laurel Valley, Shadows-on-the-Teche,
# the City of St. Martinville), FortWiki and The Cultural Landscape Foundation. Louisiana State Parks' pages answer
# HTTP 403 here, so the hours of the four state historic sites are written "not checked".
from data_b import N
from data_ma import W
BATCH={'key':'la_hwwt','label':'Across Louisiana: steam pumps, earthworks, Creole houses and a burned villa\'s garden','added':'2026-11-22 15:28'}
LSP='Louisiana State Parks runs it; its pages could not be opened when this was written, so hours and fees are not checked: look them up before going.'
PLACES=[
# ---- Shreveport and the northwest ----
N('shreveport-water-works-museum','Shreveport Water Works Museum (McNeil Street Pumping Station)','Shreveport','la','water','standing',32.51769,-93.7571,'site','open','drive','','1887–1980',
  'Shreveport\'s first waterworks, opened in 1887 on what is now North Common Street beside Twelve Mile Bayou. It added filtration in 1890 and, the museum says, was among the first plants in the country to treat water with chlorine, in 1911. The city bought it from its private operator in 1917 and kept the steam pumps running through the 1970s; when it shut in 1980 it was the last steam-powered waterworks in the United States. It is a National Historic Landmark and a National Historic Civil Engineering Landmark.',
  'A group of mostly brick buildings holding the pumping and filtering machinery where it worked, from 1892 to about 1921: steam pumps, filters and the rest, restored. Guided or self-guided tours inside. The Shreveport Railroad Museum is on the same grounds.',
  'The last steam waterworks in America, with its engines still in place.',
  accn='Run by the McNeill Street Pumping Station Preservation Society; free admission; group tours on request (museum page, read November 22, 2026). At 142 North Common Street.',
  links=[W('Shreveport Waterworks Pumping Station'),['Shreveport Water Works Museum','https://shreveportwaterworks.org/waterworks-museum']],
  brick='?',hours='Tuesday to Saturday 10 a.m. to 4 p.m.; Sunday noon to 4 p.m.; free'),
N('strand-theatre-shreveport','Strand Theatre','Shreveport','la','civic','standing',32.51022,-93.74992,'exact','open','drive','','1925–',
  'A vaudeville house opened in 1925 by Julian and Abraham Saenger of Shreveport, whose Saenger Amusements Company ran theatres across the South; its builders billed it "the greatest theatre of the South". It turned to films by the 1940s and closed in 1977. Saved from demolition by local people and restored over about seven years, it reopened on December 21, 1984, and is now the official state theatre of Louisiana, staging touring Broadway shows and concerts.',
  'The National Register nomination, as quoted by 64 Parishes, called it one of the few largely unaltered grand movie-and-vaudeville palaces of the 1920s. The inside is seen by going to a show; interior not otherwise checked.',
  '',
  accn='A working nonprofit theatre at 619 Louisiana Avenue. The box office hours are from the theatre\'s own page, read November 22, 2026; it opens two hours before weekend shows.',
  links=[W('Strand Theatre (Shreveport, Louisiana)'),['The Strand: box office','https://www.thestrandtheatre.com/?p=17'],['64 Parishes: Strand Theatre','https://64parishes.org/entry/strand-theatre']],
  brick='?',hours='Box office Tuesday and Thursday noon to 4 p.m., and two hours before weekend shows'),
N('shreveport-central-railroad-station','Central Railroad Station','Shreveport','la','rail','standing',32.50878,-93.74526,'site','view','drive','stations','1910–',
  'A passenger station built in 1910 by the Louisiana and Arkansas Railroad, later part of the Kansas City Southern. By the early 1940s the L&A and the Cotton Belt had moved their trains to Shreveport Union Station. The station and the small freight depot just north of it were listed on the National Register in 1991.',
  'The station building in an Italian Renaissance and Spanish Colonial Revival style. Wikipedia says it is now a bar and dance club; interior not checked.',
  '',
  accn='Privately used; look from the street. Not checked on the ground.',
  links=[W('Shreveport Central Railroad Station')],
  brick='?'),
N('germantown-colony-minden','Germantown Colony','Minden','la','town','standing',32.6995,-93.23094,'site','open','drive','','1836–1871',
  'The earliest religious commune in Louisiana, founded in 1836 by German followers of Maximilian Ludwig, the "Count of Leon", led by his widow, the Countess Elisa Leon. Everything was owned in common and religious rules were kept. It lasted as a commune until 1871. There were once many houses, barns, stores and shops, a kitchen and dining hall and a "bachelor\'s hall".',
  'Most of the buildings are gone. Two hewn-log buildings with dovetailed corners survive, the Countess Leon\'s house and the kitchen and dining hall, with a barn, a well and newer log buildings round them. Wikipedia says the site was still run as a museum in 2022.',
  'A German utopia in the pine woods of north Louisiana.',
  accn='The Germantown Colony Museum, 200 Museum Road, about 7 miles north of Minden off US 79. The state museum page that once gave its hours could not be opened (it answers "not found"); hours not checked.',
  links=[W('Germantown Colony and Museum')],
  brick='no',hours='?'),
# ---- Northeast Louisiana ----
N('biedenharn-house-monroe','Biedenharn House and gardens','Monroe','la','landmark','standing',32.5197,-92.1312,'site','open','drive','','1913–',
  'The house Joseph A. Biedenharn built in 1913 beside the Ouachita River. In 1894, in Vicksburg, Mississippi, he is credited with being the first to bottle Coca-Cola. His daughter Emma Louise ("Emy-Lou") Biedenharn lived here until her death in 1984; she collected Bibles and religious art and laid out the gardens, named Elsong after a song written for her.',
  'The house, furnished as it was in Emy-Lou Biedenharn\'s time and open for tours, the gardens (Four Seasons, Oriental and a musical grotto), a Bible museum and a Coca-Cola museum opened in 2008.',
  '',
  accn='Biedenharn Museum and Gardens, 2006 Riverside Drive. Adults $12 (museum\'s own page, read November 22, 2026).',
  links=[W('Biedenharn Museum and Gardens'),['Biedenharn Museum and Gardens','https://bmuseum.org/']],
  brick='?',hours='Tuesday to Saturday 10 a.m. to 5 p.m.'),
N('frogmore-plantation-gins','Frogmore Plantation and gins','Frogmore','la','industry','standing',31.60578,-91.66864,'site','open','drive','','1843–',
  'A cotton plantation near Ferriday, still a working farm, opened for history tours in 1997 by its owners. Its manor house, Gillespie, a Greek Revival house of about 1843, was destroyed by fire in July 2019. The owners speak plainly about the enslaved people whose labour built the place.',
  'The owners count 19 preserved antebellum buildings, among them a row of cabins of the enslaved, and a rare steam-powered cotton gin: a Munger System gin (the Piazza Cotton Gin), moved here from elsewhere. A modern gin runs in season; the owners say to come from mid-September to the end of October to see it working. Tours begin on arrival and last about 90 minutes.',
  'A steam cotton gin on a farm that still grows and gins cotton.',
  accn='Privately owned; tours from the owners\' office at 11656 US 84. Adults $20 (owners\' page, read November 22, 2026). Arrive at least two hours before closing. Winter hours vary: call 318-757-2453.',
  links=[W('Frogmore Plantation'),['Frogmore: hours and admission','https://tourlouisiana.com/attractions/frogmore-plantation-hours-and-admission']],
  brick='?',hours='Mar to May and Sep to Nov 15: Mon to Fri 9 a.m. to 3 p.m. (some Saturdays 10 to 3); Jun to Aug: Mon to Fri 9 a.m. to 1 p.m.; winter by call'),
# ---- Central Louisiana ----
N('kent-house-alexandria','Kent Plantation House','Alexandria','la','landmark','standing',31.30342,-92.48293,'site','open','drive','','1800–',
  'Pierre Baillio built the house on a Spanish land grant of about 1794; the marker at the gate says it was finished in 1800. It is the oldest known standing building in Rapides Parish and, Wikipedia says, in Central Louisiana. It was listed on the National Register in 1971.',
  'A Creole house built with bousillage (clay mixed with grass) between the timbers, furnished and restored inside, with restored outbuildings: a milk house of 1820 to 1830 and a kitchen with an open hearth among them. Guided tours go through the house.',
  '',
  accn='Kent House, 3601 Bayou Rapides Road. Adults $15; tours begin at the gift shop; closed on the main winter holidays (Kent House tour page, read November 22, 2026).',
  links=[W('Kent Plantation House'),['Kent House: tours','https://kenthouse.org/tours']],
  brick='?',hours='Tours Monday to Saturday at 9, 10 and 11 a.m. and 1, 2 and 3 p.m.'),
N('forts-randolph-buhlow-pineville','Forts Randolph and Buhlow earthworks','Pineville','la','fort','traces',31.32424,-92.44946,'site','public','walk','forts','1864–1865',
  'Two Confederate earthwork forts begun in June 1864 on the east bank of the Red River, guarding the rapids against an expected third Union push up the valley. They were named for the engineer Christopher Meyer Randolph and his assistant, Lieutenant A. Buhlow. They saw no fighting and were handed to Union forces in June 1865, then pulled apart for their lumber and brick. The site, which became a state historic site in 1999, also takes in the remains of Bailey\'s Dam, the dam that let Admiral Porter\'s fleet escape down the rapids in 1864.',
  'FortWiki says a large part of the earthworks survives: Fort Randolph is a tall round work ringed by a wooden walkway, with another walkway up into the interior. On its 2020 visit hurricanes had blocked the walkways with fallen trees; their state now is not checked. A visitor centre shows a painting of the two forts.',
  '',
  accn='Forts Randolph and Buhlow State Historic Site, on US 71 at the Red River in Pineville; Fort Randolph is south of the highway and Fort Buhlow about 500 yards away to the north. The site is state land (a state historic site since 1999, FortWiki). '+LSP,
  links=[W('Forts Randolph and Buhlow State Historic Site'),['FortWiki: Fort Randolph','https://fortwiki.com/Fort_Randolph_(Louisiana)']],
  brick='no',hours='?'),
# ---- The Felicianas and Baton Rouge ----
N('port-hudson-earthworks','Port Hudson siege earthworks','Jackson','la','fort','traces',30.69159,-91.27906,'area','public','hike','forts','1863',
  'Part of the Confederate fortifications and battlefield of Port Hudson, on the Mississippi north of Baton Rouge, besieged by Union troops from May 23 to July 9, 1863, the longest siege in American history according to Wikipedia. It is a National Historic Landmark, chiefly as the first place where African American units fought for the Union army under African American field officers.',
  'Redoubts and earthworks with artillery on display and interpretive signs, a museum of the siege, and a cemetery. Pictures in the article show the Fort Desperate earthworks and the Alabama-Arkansas Redoubt beside Foster Creek. Re-enactments are held each year.',
  '',
  accn='Port Hudson State Historic Site, on the west side of US 61 north of the community of Port Hudson. '+LSP,
  links=[W('Port Hudson State Historic Site')],
  brick='no',hours='?'),
N('afton-villa-gardens-ruins','Afton Villa Gardens and mansion ruins','St. Francisville','la','landmark','ruins',30.8479,-91.3875,'area','open','walk','burned','1849–1963',
  'William Barrow\'s land, bought by his brother Bartholomew in 1820 and sold to his son David Barrow in 1839. David Barrow and his second wife, Susan Woolfolk, built a Gothic Revival mansion here in 1849 and laid out more than 25 acres of gardens. The estate fell into neglect after 1876, was restored from 1915 and redesigned in the 1940s; the house burned in 1963. From 1972 Genevieve and Morrell Trimble brought the gardens back and turned the ruins of the mansion into a garden.',
  'The ruins garden on the site of the burned house, a half-mile drive under live oaks, a formal parterre and boxwood maze, seven terraces down a hillside, and the Barrow family cemetery, where Senator Alexander Barrow was buried in 1846.',
  'A Gothic mansion gone to fire, its footprint now a garden.',
  accn='Privately owned and open in spring (March 1 to June 30) and fall (October 1 to November 30) seasons; adults $12 (gardens\' own page, read November 22, 2026). On US 61 north of St. Francisville.',
  links=[W('Afton Villa Gardens'),['Afton Villa Gardens','https://aftonvillagardens.com/'],['The Cultural Landscape Foundation: Afton Villa Gardens','https://www.tclf.org/afton-villa-gardens']],
  brick='?',hours='Spring Mar 1 to Jun 30 and fall Oct 1 to Nov 30: daily 9 a.m. to 4:30 p.m.'),
N('grace-church-st-francisville','Grace Episcopal Church','St. Francisville','la','worship','standing',30.77583,-91.38722,'site','open','drive','','1858–',
  'The congregation was organized in 1827 and is one of the oldest Protestant congregations in Louisiana. The present church was finished in 1860 and badly damaged by Union gunboats in 1863; it was repaired and rebuilt in 1893, which gave it its present look.',
  'A Gothic Revival church whose organ dates from 1860. Interior not checked beyond that.',
  '',
  accn='An active Episcopal parish (Grace Church of West Feliciana Parish); service times from its own page, read November 22, 2026.',
  links=[W('Grace Episcopal Church (St. Francisville, Louisiana)'),['Grace Church of West Feliciana','https://gracechurchwfp.org/home/?p=25']],
  brick='?',hours='Sunday services 7:30 and 10 a.m.'),
N('magnolia-mound-baton-rouge','Magnolia Mound','Baton Rouge','la','landmark','standing',30.42627,-91.18725,'site','open','drive','','1791–',
  'A French Creole house begun about 1791 as a small settler\'s house near the Mississippi and enlarged in 1802 to 1805 as the seat of a 900-acre plantation; it is one of the earliest buildings in Baton Rouge. Period papers call it Mount Magnolia. The city\'s recreation commission (BREC) owns it and runs it as a museum.',
  'The house keeps its cypress frame with bousillage between the posts, original cypress floors, a rare cove ceiling and Federal woodwork, and is furnished with Louisiana-made pieces. Round it: a rebuilt open-hearth kitchen (cooking shown October to May), a double cabin of the enslaved of about 1830 moved from Pointe Coupee Parish, a pigeonnier of about 1825, the overseer\'s house of about 1871 and a three-seat privy.',
  'Bousillage walls and a cove ceiling a mile from the state capitol.',
  accn='BREC\'s Magnolia Mound: Museum and Historic Site. Guided tours adults $12; grounds self-guided $5; free on the first Sunday of some months (BREC page, read November 22, 2026). The page gave no regular hours: check before going.',
  links=[W('Magnolia Mound Plantation House'),['BREC: Magnolia Mound','https://www.brec.org/magnoliamound']],
  brick='no',hours='?'),
N('pentagon-barracks-baton-rouge','Pentagon Barracks','Baton Rouge','la','fort','standing',30.45552,-91.18933,'site','view','drive','forts','1819–1825',
  'United States Army barracks designed by Captain James Gadsden and built from 1819 to 1825 just north of the old Spanish Fort San Carlos, which the army tore down. Four two-storey brick buildings formed four sides of a pentagon (the fifth, a warehouse, was built in 1821 and pulled down within months as faulty). Zachary Taylor, Lafayette, Robert E. Lee, Jefferson Davis and Abraham Lincoln are among the visitors Wikipedia names. LSU used the buildings as dormitories from 1886 until 1926, and the state took ownership in 1951.',
  'The four brick barracks blocks round an open lawn on the capitol grounds. They hold the lieutenant governor\'s offices and apartments for legislators, so the inside is not open; seen from the grounds.',
  '',
  accn='State of Louisiana, at State Capitol Drive and River Road beside the capitol. Not checked on the ground.',
  links=[W('Pentagon Barracks')],
  brick='?'),
# ---- Bayou country ----
N('laurel-valley-plantation','Laurel Valley Sugar Plantation','Thibodaux','la','industry','standing',29.81214,-90.77259,'site','open','drive','','1816–',
  'Etienne Boudreaux, an Acadian, bought a Spanish land grant on Bayou Lafourche in 1785; his family house of 1816 is the oldest building on the place. Joseph W. Tucker of Virginia bought the land in 1832 and built a sugar mill; it became the largest sugar producer in Lafourche Parish. Union soldiers burned Tucker\'s house in the Civil War. Enslaved people, free people of colour, Acadians, Creoles and Irish, Italian and Chinese workers lived in the quarters over the years.',
  'About 40 original buildings, the largest surviving 19th- and 20th-century sugar plantation complex in the United States, on a farm that still grows cane: Creole cabins of about 1845 and shotgun houses of about 1895 among them. A 1979 survey photograph on Wikimedia Commons shows the roofless red-brick walls of the ruined sugar mill on the grounds; their state now is not checked. Seen on guided tours booked ahead. The plantation store of 1905, about two miles away on LA 308, is a museum with old wagons, tractors and two cane locomotives (not the originals).',
  'A whole sugar village of cabins and shotguns, still in the cane fields.',
  accn='The Laurel Valley Heritage Foundation runs tours of the village: book online at least 48 hours ahead, or call (985) 492-0782 the same day. The store and museum is at 595 LA 308 (foundation pages, read November 22, 2026). The fields round the village are a working farm: go with the tour.',
  links=[W('Laurel Valley Sugar Plantation'),['Laurel Valley Plantation','https://laurelvalleyplantation.com/'],['Laurel Valley Store and Museum','https://laurelvalleyplantation.com/laurel-valley-store-museum']],
  brick='some',hours='Store and museum daily 10:30 a.m. to 4:30 p.m. (volunteer-run, may vary); village by booked tour'),
N('shadows-on-the-teche','Shadows-on-the-Teche','New Iberia','la','landmark','standing',30.00439,-91.81566,'site','open','walk','','1834–',
  'A town house built in 1834 on Bayou Teche for the planter David Weeks and his wife Mary Conrad Weeks; he died that year while away seeking treatment. Their household depended on enslaved labour. Union officers were quartered in part of the house when Mary Weeks died there in December 1863. The last private owner, William Weeks Hall, who died in 1958, laid out the gardens; the National Trust for Historic Preservation now owns and runs the house, a National Historic Landmark.',
  'A two-and-a-half-storey Greek Revival house of handmade red brick, with eight plastered brick columns across the front, a Creole plan with no inner hallways, a checkered marble dining-room floor, cypress doors painted to look like oak, a domed underground brick cistern, a summer house of 1928 and the Weeks family cemetery. Guided tours go inside.',
  '',
  accn='National Trust for Historic Preservation. Tours start at the visitor centre, 320 East Main Street; attendance limited, booking ahead advised (Shadows hours page, read November 22, 2026).',
  links=[W('Shadows-on-the-Teche'),['Shadows: hours and admission','https://www.shadowsontheteche.org/hours-admission']],
  brick='yes',hours='Thursday to Saturday 10 a.m. to 4 p.m.; tours 10:30 a.m. and 2 p.m. (11:30 a.m. too on some dates)'),
N('st-martin-de-tours-st-martinville','St. Martin de Tours Church','St. Martinville','la','worship','standing',30.12278,-91.82806,'site','open','drive','','1840–',
  'The church of the Attakapas district, founded in 1765 by Father Jean-Louis de Civrey with Acadian refugees and long called l\'Église des Attakapas. The present church was finished in 1840 and consecrated in 1844 as a plain basilica-plan church with Doric columns between nave and aisles; transepts, an apse and a longer nave were added in the 1870s. Beside it are a monument to the St. Martinville militiamen who fought under Gálvez at Baton Rouge in 1779 and the statue of Evangeline over her supposed grave.',
  'Inside, the city says, are a painting of St. Martin de Tours by Jean-François Moucher and a grotto of Lourdes; the square also holds the old cemetery and an adoration garden. Wider interior not checked.',
  'The mother church of the Acadians, with Evangeline\'s statue in the yard.',
  accn='An active Catholic parish on the church square, 133 South Main Street. The City of St. Martinville says it holds daily Masses; the parish\'s own site could not be opened, so the times are not checked. The square is always open.',
  links=[W('St. Martin of Tours Catholic Church (St. Martinville, Louisiana)'),['City of St. Martinville: attractions','https://stmartinville.gov/attractions/']],
  brick='?',hours='?'),
N('maison-olivier-st-martinville','Maison Olivier (Longfellow-Evangeline State Historic Site)','St. Martinville','la','landmark','standing',30.13387,-91.82675,'site','open','walk','','c. 1815–',
  'A raised Creole cottage built about 1815 by Pierre Olivier Duclozel de Vezin, a wealthy Creole, and a National Historic Landmark (as the Acadian House) since 1974. It stands in the oldest of Louisiana\'s state park sites, founded in 1934 around Longfellow\'s poem Evangeline.',
  'The house, behind the visitor centre, with a blacksmith shop nearby, an Acadian cabin of about 1790, and a reproduction Acadian farmstead near Bayou Teche. Interior not checked.',
  '',
  accn='Longfellow-Evangeline State Historic Site, on the north side of St. Martinville. '+LSP,
  links=[W('Longfellow-Evangeline State Historic Site')],
  brick='?',hours='?'),
N('calcasieu-parish-courthouse','Calcasieu Parish Courthouse','Lake Charles','la','civic','standing',30.22639,-93.21833,'exact','view','drive','','1912–',
  'The parish\'s courthouses began with a log cabin of 1841 at Marion, moved to Lake Charles when it became the parish seat in 1852. A brick courthouse of 1891 was destroyed in the great fire of 1910, and this one was finished in 1912, designed by the firm Favrot and Livaudais as a copy of Palladio\'s Villa Capra ("La Rotonda") near Vicenza.',
  'A domed courthouse whose dome is solid copper. A working courthouse; interior not checked.',
  '',
  accn='Calcasieu Parish; look from the square. Not checked on the ground.',
  links=[W('Calcasieu Parish Courthouse')],
  brick='?'),
]
